import { BrowserEmulatorSession } from "./emulator/session.js";
import { TasMovie, TasPlaybackEngine } from "./emulator/tas-player.js";
import { bitsToMask, firstConnectedGamepad, gamepadInputMask, nesBits } from "./input.js";
import { ScoreRunTracker, calculateScore, filterMemoryCandidates, scoreFormulaLabels } from "./emulator/score-tools.js";

const root = document.querySelector("#mini-game-maker");
const emulator = new BrowserEmulatorSession();
const timeline = new TasPlaybackEngine(emulator);
const defaultControls = { keyboard:{b:"z",a:"x",select:"shift",start:"enter",up:"arrowup",down:"arrowdown",left:"arrowleft",right:"arrowright"}, gamepad:{b:1,a:0,select:8,start:9,up:12,down:13,left:14,right:15} };
const state = { stage:"games", catalog:{games:[],challenges:[]}, game:null, inputMask:0, pressed:new Set(), controls:defaultControls, live:false, creatorControl:false, creator:null, verification:null, verifyResult:null, editorTab:"rules", ruleEditor:null, modifierEditor:null, modifierCatalog:[], scoreSearch:{baseline:null,candidates:null,comparison:"changed"}, scoreDraft:{title:"",entries:[]}, scoreDraftTracker:null, scoreRunBaseline:null, scoreTracker:null, saving:false, notice:"" };
const html = (value) => String(value??"").replace(/[&<>"']/g,(c)=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]);
async function api(path,options={}){const config={...options,headers:{"Content-Type":"application/json",...(options.headers||{})}};if(config.body&&typeof config.body!=="string")config.body=JSON.stringify(config.body);const response=await fetch(path,config),data=await response.json();if(!response.ok||data.error)throw new Error(data.error||"Mini-Game Maker could not complete that action.");return data;}
function notify(message){state.notice=message;const node=document.querySelector("#maker-notice");if(node)node.textContent=message;}
function controlLabel(action){const key=state.controls.keyboard[action]||defaultControls.keyboard[action]||action;return key.length===1?key.toUpperCase():key.replace("arrow","").toUpperCase();}
function frame(content,{title="MINI-GAME MAKER",kicker="STANDALONE CREATION APP",back="main"}={}){const backControl=back==="main"?`<a class="maker-back" href="/">◀ MAIN MENU</a>`:`<button type="button" data-go="${back}">◀ ${back==="games"?"GAMES":"MINI-GAMES"}</button>`;return `<section class="maker-app"><header class="maker-bar">${backControl}<div><small>${html(kicker)}</small><b>${html(title)}</b></div>${back==="main"?"":`<a href="/">MAIN MENU</a>`}</header><main>${content}</main><footer><span id="maker-notice">${html(state.notice||"READY")}</span><span>MOVE ${controlLabel("up")}/${controlLabel("down")}/${controlLabel("left")}/${controlLabel("right")} · B ${controlLabel("b")} · A ${controlLabel("a")} · START ${controlLabel("start")}</span></footer></section>`;}
function gamesView(){const cards=state.catalog.games.map(game=>{const count=state.catalog.challenges.filter(c=>c.gameId===game.id||c.gameTitle===game.title).length;return `<button type="button" class="maker-game-card" data-game="${html(game.id)}"><img src="${html(game.boxArtUrl||`/boxart/${game.id}.png`)}" alt="" onerror="this.src='/fallback-art.png'"><b>${html(game.title)}</b><small>${html(game.genres?.[0]||game.series||"NES")} · ${count} MINI-GAME${count===1?"":"S"}</small></button>`;}).join("");return frame(`<section class="maker-browser"><header><small>MINI-GAME CATALOGUE</small><h1>CHOOSE A CARTRIDGE</h1><p>Choose a game to see its mini-games or create a new one.</p></header><div class="maker-game-grid">${cards||`<div class="maker-empty">No browser-compatible games were found.</div>`}</div></section>`);}
function miniGamesView(){const challenges=state.catalog.challenges.filter(c=>c.gameId===state.game.id||c.gameTitle===state.game.title||c.gameName===state.game.title);return frame(`<section class="maker-browser"><header><small>MINI-GAME CATALOGUE</small><h1>${html(state.game.title)} MINI-GAMES</h1></header><div class="maker-challenge-grid"><button type="button" class="maker-new-card" data-record-new><span>＋</span><b>NEW MINI-GAME</b><small>Open Moment Maker and record a starting moment.</small></button>${challenges.map(c=>`<button type="button" class="maker-challenge-card" data-challenge="${html(c.id)}"><span>★</span><div><b>${html(c.title)}</b><p>${html(c.instructions||c.description||"Complete the challenge goal.")}</p><small>${html(c.difficulty||"Medium")} · ${html(c.category||"Skill")}</small></div></button>`).join("")}</div></section>`,{title:`${state.game.title} MINI-GAMES`,kicker:"MINI-GAME CATALOGUE",back:"games"});}
function screen(id){return `<div class="maker-screen"><canvas id="${id}" width="256" height="240"></canvas><div class="scanlines"></div></div>`;}
function momentView(){const current=timeline.currentFrame||0,total=timeline.movie?.totalFrames||0;return frame(`<section class="moment-workspace"><div class="transport"><button data-transport="restart">↺ RESTART</button><button data-transport="back60">◀◀ 1s</button><button data-transport="back">◀ FRAME</button><button data-transport="play">${state.live||timeline.isPlaying?"❚❚ PAUSE":"▶ PLAY"}</button><button data-transport="forward">FRAME ▶</button><button data-transport="forward60">1s ▶▶</button><button class="record ${state.live?"active":""}" data-transport="record">● ${state.live?"STOP RECORDING":"RECORD"}</button></div>${screen("moment-canvas")}<div class="timeline-panel"><div><b id="maker-timecode">${TasMovie.formatTimecode(current)} / ${TasMovie.formatTimecode(total)}</b><span id="maker-frame">FRAME ${current} / ${total}</span></div><input id="maker-slider" type="range" min="0" max="${Math.max(1,total)}" value="${current}" step="1"><nav>${[.25,.5,1,2,4].map(speed=>`<button data-speed="${speed}" class="${timeline.playbackSpeed===speed?"active":""}">${speed}x</button>`).join("")}</nav></div><div class="moment-actions"><p>Press Record, then play with the keyboard or controller. Scrub back to choose the exact starting state.</p><button class="primary" data-open-designer>MAKE MINI-GAME ▶</button></div></section>`,{title:state.game.title,kicker:"MOMENT MAKER · LIVE DVR TIMELINE",back:"minigames"});}
function ruleCards(){const creator=state.creator||emulator.creatorSummary(),goals=creator?.milestones||[],losses=creator?.lossGuards||[],scores=creator?.scoring||[],recording=creator?.mode==="recording",verifying=creator?.mode==="verification",goalStatuses=creator?.ledger?.statuses||[];return `<div class="learned-rules" id="learned-rules"><section><header><b>GOALS</b><small>${goals.length}</small></header>${goals.map((g,index)=>{const reached=Boolean(goalStatuses[index]);return `<div class="${verifying?(reached?"rule-reached":"rule-waiting"):""}"><span>⚡</span><p><b>${html(g.title)}</b><small>${html(g.condition?.description||"Learned memory condition")}</small><em>${g.hits||1} DEMONSTRATION${(g.hits||1)===1?"":"S"}</em></p>${recording?`<button type="button" class="reinforce goal" data-reinforce-goal="${html(g.id)}" aria-label="Reinforce ${html(g.title)}" title="Hit goal">👍</button>`:verifying?`<strong class="rule-state">${reached?"● REACHED":"○ WAITING"}</strong>`:`<button type="button" class="rule-edit" data-edit-rule="goal:${html(g.id)}" aria-label="Edit ${html(g.title)}" title="Edit goal">✎</button>`}</div>`;}).join("")||`<em>Play a demonstration and mark the winning moment.</em>`}</section><section><header><b>LOSS GUARDS</b><small>${losses.length}</small></header>${losses.map(g=>`<div class="${verifying?"rule-armed":""}"><span>✕</span><p><b>${html(g.title)}</b><small>${html(g.condition?.description||"Learned memory condition")}</small><em>${g.hits||1} DEMONSTRATION${(g.hits||1)===1?"":"S"}</em></p>${recording?`<button type="button" class="reinforce loss" data-reinforce-loss="${html(g.id)}" aria-label="Reinforce ${html(g.title)}" title="Trigger loss guard">👎</button>`:verifying?`<strong class="rule-state">○ ARMED</strong>`:`<button type="button" class="rule-edit" data-edit-rule="loss:${html(g.id)}" aria-label="Edit ${html(g.title)}" title="Edit loss guard">✎</button>`}</div>`).join("")||`<em>Optionally mark a failed attempt.</em>`}</section><section class="saved-scores"><header><b>SCORE CALCULATORS</b><small>${scores.length}</small></header>${scores.map(score=>{const entries=score.entries?.length?score.entries:[score];return `<div><span>◆</span><p><b>${html(score.name||"Score")}</b><small>${entries.length} TRACKED VALUE${entries.length===1?"":"S"}</small><em>${entries.map(entry=>`$${Number(entry.address).toString(16).toUpperCase().padStart(4,"0")} · ${html(scoreFormulaLabels[entry.formula]||entry.formula||"Final value")}`).join(" · ")}</em></p></div>`;}).join("")||`<em>No score calculator saved for this mini-game.</em>`}</section></div>`;}
function modifierTab(){const modifiers=emulator.modifiers||[];return `<div class="modifier-list tab-modifier-list">${modifiers.map(mod=>{const writes=mod.entries?.length||1;return `<article class="modifier-editor ${mod.enabled?"active":""}"><header><span><b>${html(mod.name||"Cheat Code")}</b><small>${html(mod.description||mod.category||"Cheat")}</small></span><strong>${mod.enabled?"ON":"OFF"} · ${writes>1?`${writes} WRITES`:html(mod.category||"CHEAT")}</strong><button type="button" class="rule-edit" data-edit-modifier="${html(mod.id)}" aria-label="Edit ${html(mod.name||"modifier")}" title="Edit modifier">✎</button></header></article>`;}).join("")||`<em>NO CHEAT CODES AVAILABLE</em>`}</div>`;}
function modifierEditorModal(){if(!state.modifierEditor)return "";const modifier=(emulator.modifiers||[]).find(item=>item.id===state.modifierEditor);if(!modifier)return "";const entries=modifier.entries?.length?modifier.entries:[{address:modifier.address,value:modifier.value}];return `<div class="modifier-edit-backdrop"><section class="modifier-edit-modal" role="dialog" aria-modal="true"><header><b>EDIT MODIFIER</b><button type="button" data-close-modifier-editor>✕</button></header><form id="modifier-editor-form" data-modifier-id="${html(modifier.id)}"><label class="modifier-name-field">NAME<input name="name" maxlength="80" required value="${html(modifier.name||"Cheat Code")}"></label><label class="modifier-enabled"><input name="enabled" type="checkbox" ${modifier.enabled?"checked":""}> ENABLE MODIFIER</label><div class="modifier-entry-list">${entries.map((entry,index)=>`<div><label class="modifier-entry-enabled"><input name="entry-enabled" type="checkbox" value="${index}" ${entry.enabled!==false?"checked":""}> USE</label><b>$${Number(entry.address||0).toString(16).toUpperCase().padStart(4,"0")}</b><span>RAM <strong data-modifier-ram-address="${Number(entry.address||0)}">${emulator.core?.peek?.(entry.address)??0}</strong></span><label>LOCKED VALUE<input name="entry-value" type="number" min="0" max="255" value="${Number(entry.value||0)}"></label><input name="entry-address" type="hidden" value="${Number(entry.address||0)}"></div>`).join("")}</div><footer><button type="button" data-lock-modifier-current>LOCK CURRENT RAM VALUE</button><button type="button" data-reset-modifier ${state.modifierCatalog.some(item=>item.id===modifier.id)?"":"disabled"}>↺ CATALOG DEFAULT</button><button type="button" class="delete-modifier" data-delete-modifier>DELETE FROM LIBRARY</button><button type="submit" class="primary">SAVE FOR MINI-GAME</button></footer></form></section></div>`;}
function scoreConfigs(){return emulator.creator?.scoring||[];}
function scoreEntries(){return scoreConfigs().flatMap(score=>score.entries?.length?score.entries:[score]);}
function clearScoreFinder(){state.scoreSearch={baseline:null,candidates:null,comparison:state.scoreSearch.comparison};state.scoreDraft={title:"",entries:[]};state.scoreDraftTracker=null;state.scoreRunBaseline=null;}
function resetDraftScoreCalculation(snapshot=emulator.captureSnapshot()){state.scoreRunBaseline=snapshot.values.slice();state.scoreDraftTracker=new ScoreRunTracker(state.scoreDraft.entries,snapshot.values);}
function draftScoreTotal(){if(!state.scoreDraftTracker)return 0;return state.scoreDraft.entries.reduce((total,entry)=>total+calculateScore(state.scoreDraftTracker.stats.get(entry.id),entry.formula),0);}
function scoreTab(){const search=state.scoreSearch,candidates=search.candidates||[],draft=state.scoreDraft,visible=candidates.slice(0,250),comparisons=[["greater",">"],["less","<"],["equal","="],["changed","!="]];return `<section class="score-tab"><div class="score-finder"><div class="score-scan-controls"><button type="button" data-score-new-scan>NEW SCAN</button><div class="score-comparisons" aria-label="Filter memory against the previous scan">${comparisons.map(([value,label])=>`<button type="button" data-score-comparison="${value}" class="${search.comparison===value?"active":""}" title="Filter values ${value} than before">${label}</button>`).join("")}</div></div><b>${search.candidates===null?"NO SCAN":`${candidates.length} MATCHES`}</b><div class="score-candidates">${visible.map(address=>`<button type="button" data-track-score="${address}" ${draft.entries.some(entry=>entry.address===address)?"disabled":""}><span>$${address.toString(16).toUpperCase().padStart(4,"0")}</span><strong data-memory-value="${address}">${emulator.core?.peek?.(address)??"–"}</strong></button>`).join("")}${candidates.length>visible.length?`<small>SHOWING FIRST ${visible.length} OF ${candidates.length}</small>`:""}</div></div><div class="score-tracked"><header><b>TRACKED VALUES</b><small>${draft.entries.length}</small></header><label class="score-title">TITLE<input data-score-draft-title maxlength="80" placeholder="Score calculator name" value="${html(draft.title)}"></label>${draft.entries.map(config=>`<article data-score-config="${html(config.id)}"><header><b>$${Number(config.address).toString(16).toUpperCase().padStart(4,"0")}</b><strong>RAM = <span data-score-live="${html(config.id)}">${emulator.core?.peek?.(config.address)??0}</span></strong></header><label>FORMULA<select data-score-field="formula" data-score-id="${html(config.id)}">${Object.entries(scoreFormulaLabels).map(([value,label])=>`<option value="${value}" ${config.formula===value?"selected":""}>${label}</option>`).join("")}</select></label><label class="score-cumulative"><input type="checkbox" data-score-field="cumulative" data-score-id="${html(config.id)}" ${config.cumulative?"checked":""}> CUMULATIVE (8-BIT WRAPAROUND)</label><div class="score-value-actions"><input data-score-set-input="${html(config.id)}" type="number" min="0" max="255" value="${Number(config.setValue??0)}"><button type="button" data-score-set="${html(config.id)}">SET</button><button type="button" data-score-lock="${html(config.id)}" class="${config.locked?"active":""}">${config.locked?"UNLOCK":"LOCK"}</button></div><div class="score-flags"><button type="button" data-score-remove="${html(config.id)}">✕ REMOVE</button></div></article>`).join("")||`<em>CLICK MEMORY ADDRESSES ABOVE TO BUILD A GROUP</em>`}<footer><button type="button" data-save-score-modifier ${draft.entries.length?"":"disabled"}>SAVE AS MODIFIER</button><button type="button" class="primary" data-save-score-group ${draft.entries.length?"":"disabled"}>SAVE AS SCORE</button></footer></div></section>`;}
function parseMemoryAddress(value){const text=String(value??"").trim().replace(/^\$/,"").replace(/^0x/i,"");return /^[0-9a-f]{1,4}$/i.test(text)?Number.parseInt(text,16):null;}
function exportTab(){const search=state.scoreSearch,candidates=search.candidates||[],visible=candidates.slice(0,250),mappings=state.creator?.memoryExports||[],comparisons=[["greater",">"],["less","<"],["equal","="],["changed","!="]];return `<section class="export-tab"><header><small>BOARD-GAME INTERFACE</small><h2>EXPORTED VARIABLES</h2><p>Search NES memory, then name values that the board game can read after this mini-game runs.</p></header><div class="score-finder export-finder"><div class="score-scan-controls"><button type="button" data-score-new-scan>NEW SCAN</button><div class="score-comparisons" aria-label="Filter memory against the previous scan">${comparisons.map(([value,label])=>`<button type="button" data-score-comparison="${value}" class="${search.comparison===value?"active":""}" title="Filter values ${value} than before">${label}</button>`).join("")}</div></div><b>${search.candidates===null?"NO SCAN":`${candidates.length} MATCHES`}</b><div class="score-candidates">${visible.map(address=>`<button type="button" data-select-export-address="${address}" ${mappings.some(item=>item.address===address)?"disabled":""}><span>$${address.toString(16).toUpperCase().padStart(4,"0")}</span><strong data-memory-value="${address}">${emulator.core?.peek?.(address)??"–"}</strong></button>`).join("")}${candidates.length>visible.length?`<small>SHOWING FIRST ${visible.length} OF ${candidates.length}</small>`:""}</div></div><form id="memory-export-form"><label>VARIABLE NAME<input name="name" required maxlength="48" pattern="[A-Za-z_][A-Za-z0-9_]*" placeholder="coins_earned" autocomplete="off"></label><label>MEMORY ADDRESS<input name="address" required maxlength="6" pattern="(?:\\$|0[xX])?[0-9A-Fa-f]{1,4}" placeholder="$075E" autocomplete="off"></label><button type="submit">+ ADD EXPORT</button></form><div class="export-list">${mappings.map(item=>`<article data-memory-export="${html(item.id)}"><label>VARIABLE NAME<input data-export-field="name" data-export-id="${html(item.id)}" maxlength="48" pattern="[A-Za-z_][A-Za-z0-9_]*" value="${html(item.name)}"></label><label>MEMORY ADDRESS<input data-export-field="address" data-export-id="${html(item.id)}" maxlength="6" pattern="(?:\\$|0[xX])?[0-9A-Fa-f]{1,4}" value="$${Number(item.address).toString(16).toUpperCase().padStart(4,"0")}"></label><span>LIVE VALUE<strong data-export-live="${html(item.id)}">${emulator.core?.peek?.(item.address)??0}</strong></span><button type="button" data-remove-export="${html(item.id)}" aria-label="Remove ${html(item.name)}" title="Remove exported variable">✕</button></article>`).join("")||`<em>NO MEMORY VARIABLES EXPORTED YET</em>`}</div></section>`;}
function verifyResultModal(){const result=state.verifyResult;if(!result)return "";return `<div class="verify-result-backdrop"><section class="verify-result-modal" role="dialog" aria-modal="true"><header><b>${result.completed?"★ VERIFY RUN COMPLETE":"✕ VERIFY RUN FAILED"}</b><button type="button" data-close-verify-result>✕</button></header><div><section><b>GOALS</b>${result.goals.map(goal=>`<span class="${goal.triggered?"hit":"miss"}">${goal.triggered?"●":"○"} ${html(goal.title)}</span>`).join("")||`<em>NO GOALS</em>`}</section><section><b>FAILURES</b>${result.failures.map(failure=>`<span class="hit">● ${html(failure)}</span>`).join("")||`<span class="clear">○ NONE TRIGGERED</span>`}</section><section><b>SCORES</b>${result.scores.map(score=>`<span><strong>${html(score.name)}</strong><em>${score.components?.length?`${score.components.length} VALUES · COMBINED TOTAL`:html(scoreFormulaLabels[score.formula]||score.formula)}</em><b>${score.score}</b></span>`).join("")||`<em>NO SCORE VALUES ENABLED</em>`}</section></div><footer><button type="button" data-close-verify-result>DONE</button></footer></section></div>`;}
function ruleEditorModal(){if(!state.ruleEditor)return "";const {type,id}=state.ruleEditor,list=type==="goal"?state.creator?.milestones:state.creator?.lossGuards,rule=list?.find(item=>item.id===id);if(!rule)return "";const selected=rule.selectedCandidateIds||[],auto=rule.autoSelectedCandidateIds?.length?rule.autoSelectedCandidateIds:(rule.candidates?.[0]?.id?[rule.candidates[0].id]:[]);return `<div class="rule-modal-backdrop"><section class="rule-modal" role="dialog" aria-modal="true" aria-label="Edit ${html(rule.title)}"><header><b>EDIT ${type==="goal"?"GOAL":"LOSS GUARD"}</b><button type="button" data-close-rule>✕</button></header><form id="rule-editor-form" data-rule-type="${type}" data-rule-id="${html(id)}"><label class="rule-name">NAME<input name="title" maxlength="80" required value="${html(rule.title)}"></label><div class="candidate-list"><header><b>REQUIRED MEMORY CHANGES</b><small>AUTO: ${auto.length}</small></header>${(rule.candidates||[]).map(candidate=>`<label class="candidate-row"><input type="checkbox" name="candidate" value="${html(candidate.id)}" ${selected.includes(candidate.id)?"checked":""}><span><b>${html(candidate.description||`Memory $${Number(candidate.address||0).toString(16).toUpperCase().padStart(4,"0")}`)}</b><small>${html(candidate.explanation||`Address $${Number(candidate.address||0).toString(16).toUpperCase().padStart(4,"0")}`)}</small></span><strong>${Number(candidate.confidence||0)}%</strong></label>`).join("")||`<em>NO ALTERNATE MEMORY CHANGES CAPTURED</em>`}</div><footer><button type="button" data-reset-rule>↺ AUTO-SET</button><button type="button" class="delete-rule" data-delete-rule>DELETE</button><button type="submit" class="primary">SAVE CHANGES</button></footer></form></section></div>`;}
function verifyButton(){const creator=state.creator||{},verifying=creator.mode==="verification",recording=creator.mode==="recording",hasGoal=Boolean(creator.selected||creator.milestones?.some(g=>g.enabled!==false&&g.condition));return `<button type="button" class="verify-button" data-verify ${!verifying&&(!hasGoal||recording)?"disabled":""}>${verifying?"■ STOP VERIFY RUN":"▶ VERIFY RUN"}</button>`;}
function editorTabs(){const creator=state.creator||{},recording=creator.mode==="recording",verifying=creator.mode==="verification",activeModifiers=(emulator.modifiers||[]).filter(mod=>mod.enabled).length,presentation=creator.presentation||{},metadata=creator.metadata||{},category=metadata.category||"Skill",difficulty=metadata.difficulty||"Medium",seconds=Math.round((creator.rules?.timeLimitFrames||900)/60);const tabs=[{id:"modifiers",label:`MODIFIERS${activeModifiers?` (${activeModifiers})`:""}`},{id:"rules",label:"GOALS & RUNS"},{id:"score",label:"SCORE"},{id:"export",label:"EXPORT"},{id:"save",label:"SAVE"}],option=(value,selected)=>`<option ${value===selected?"selected":""}>${value}</option>`;const rules=`<div class="demo-controls side-demo-controls"><button data-demo="start" ${verifying?"disabled":""}>${recording?"↺ RESTART DEMO":"▶ START DEMO"}</button><button data-demo="goal" ${recording?"":"disabled"}>⚡ + GOAL</button><button data-demo="loss" ${recording?"":"disabled"}>✕ + LOSS</button><button data-demo="stop" ${recording?"":"disabled"}>■ STOP</button></div>${ruleCards()}${verifyButton()}`;const save=`<form id="challenge-form"><h2>PACKAGE THE MINI-GAME</h2><label>TITLE<input name="title" required value="${html(presentation.title||`${state.game.title} Challenge`)}"></label><label>INSTRUCTIONS<textarea name="instructions" required>${html(presentation.instructions||"Complete the goal before time runs out!")}</textarea></label><div class="form-row"><label>CATEGORY<select name="category">${["Skill","Speed","Survival","Puzzle","Score Attack"].map(value=>option(value,category)).join("")}</select></label><label>DIFFICULTY<select name="difficulty">${["Easy","Medium","Hard"].map(value=>option(value,difficulty)).join("")}</select></label><label>SECONDS<input name="time" type="number" min="1" max="600" value="${seconds}"></label></div><button class="primary" type="submit" ${state.saving?"disabled":""}>${state.saving?"SAVING…":"SAVE TO SERVER ★"}</button></form>`;const content=state.editorTab==="modifiers"?modifierTab():state.editorTab==="score"?scoreTab():state.editorTab==="export"?exportTab():state.editorTab==="save"?save:rules;return `<aside class="designer-sidebar"><nav class="editor-tabs">${tabs.map(tab=>`<button type="button" data-editor-tab="${tab.id}" class="${state.editorTab===tab.id?"active":""}">${tab.label}</button>`).join("")}</nav><div class="editor-tab-panel">${content}</div></aside>`;}
function designerView(){return frame(`<section class="designer-workspace"><div class="designer-grid"><div class="designer-player">${screen("designer-canvas")}<button class="control ${state.creatorControl?"active":""}" data-control-game>🎮 ${state.creatorControl?"PAUSE GAME CONTROL":"CONTROL GAMEPLAY"}</button></div>${editorTabs()}</div></section>${ruleEditorModal()}${modifierEditorModal()}${verifyResultModal()}`,{title:`${state.game.title} MINI-GAME`,kicker:"MINI-GAME DESIGNER · GOAL & RULE COMPILER",back:"minigames"});}
function render(){if(state.stage==="games")root.innerHTML=gamesView();else if(state.stage==="minigames")root.innerHTML=miniGamesView();else if(state.stage==="moment")root.innerHTML=momentView();else root.innerHTML=designerView();const newScan=root.querySelector("[data-score-new-scan]");if(newScan&&!root.querySelector("[data-score-reset-run]"))newScan.insertAdjacentHTML("afterend",`<button type="button" class="score-reset-run" data-score-reset-run aria-label="Reset mini-game run" title="Reset mini-game run without clearing search">↺</button>`);for(const article of root.querySelectorAll(".score-tracked>article")){const remove=article.querySelector("[data-score-remove]"),header=article.querySelector("header");if(remove&&header){remove.textContent="✕";remove.className="score-remove-icon";remove.setAttribute("aria-label","Remove tracked memory address");remove.title="Remove tracked memory address";header.append(remove);article.querySelector(".score-flags")?.remove();}}const scoreFooter=root.querySelector(".score-tracked>footer");if(scoreFooter)scoreFooter.insertAdjacentHTML("beforebegin",`<div class="score-draft-total"><span>ESTIMATED SCORE</span><strong data-score-draft-total>${draftScoreTotal()}</strong></div>`);bindCanvas();requestAnimationFrame(()=>root.querySelector("button,a,input")?.focus());}
function drawOutput(canvas,output){if(!canvas||!output?.video)return;canvas.getContext("2d",{alpha:false}).putImageData(new ImageData(new Uint8ClampedArray(output.video.buffer,output.video.byteOffset,output.video.byteLength),output.width,output.height),0,0);}
function stopTimelineActivity(){timeline.pause();state.live=false;state.pressed.clear();state.inputMask=0;}
