function bindCanvas(){const canvas=document.querySelector(state.stage==="moment"?"#moment-canvas":"#designer-canvas"),output=state.stage==="moment"?timeline.lastOutput:emulator.core?.getFrame?.();if(canvas)drawOutput(canvas,output);const slider=document.querySelector("#maker-slider");if(slider)slider.onchange=async()=>{if(!hasRecordedFrames())return;stopTimelineActivity();await timeline.seekTo(Number(slider.value));render();};}
async function loadAvailableModifiers(gameId){const packaged=new Map((emulator.modifiers||[]).map(item=>[item.id,item])),result=await api(`/api/library/${gameId}/modifiers`).catch(()=>({modifiers:[]}));state.modifierCatalog=(result.modifiers||[]).map(item=>structuredClone(item));const merged=state.modifierCatalog.map(item=>packaged.has(item.id)?{...item,...packaged.get(item.id)}:item);for(const item of packaged.values())if(!merged.some(candidate=>candidate.id===item.id))merged.push(item);emulator.setAvailableModifiers(merged);}
