function updateTimeline(info,output){drawOutput(document.querySelector("#moment-canvas"),output);const slider=document.querySelector("#maker-slider");if(slider){slider.max=Math.max(1,info.totalFrames);slider.value=info.currentFrame;}const time=document.querySelector("#maker-timecode");if(time)time.textContent=`${info.timecode} / ${info.totalTimecode}`;const frame=document.querySelector("#maker-frame");if(frame)frame.textContent=`FRAME ${info.currentFrame} / ${info.totalFrames}`;}
