root.addEventListener("click",async event=>{try{const destination=event.target.closest("[data-go]")?.dataset.go;if(destination){stopTimelineActivity();stopCreatorControl();state.ruleEditor=null;state.modifiersOpen=false;state.stage=destination;render();return;}const gameButton=event.target.closest("[data-game]");if(gameButton){state.game=state.catalog.games.find(item=>item.id===gameButton.dataset.game);state.stage="minigames";render();return;}if(event.target.closest("[data-record-new]"))return await loadGame(state.game,"moment");const challenge=event.target.closest("[data-challenge]");if(challenge)return await editChallenge(challenge.dataset.challenge);if(event.target.closest("[data-open-designer]"))return await openDesigner();if(event.target.closest("[data-toggle-modifiers]")){state.modifiersOpen=true;render();return;}if(event.target.closest("[data-close-modifiers]")){state.modifiersOpen=false;render();return;}const editRule=event.target.closest("[data-edit-rule]");if(editRule){const [type,id]=editRule.dataset.editRule.split(":");state.ruleEditor={type,id};render();document.querySelector("#rule-editor-form input[name=title]")?.focus();return;}if(event.target.closest("[data-close-rule]")){state.ruleEditor=null;render();return;}if(event.target.closest("[data-reset-rule]")){state.creator=emulator.resetCreatorRule(state.ruleEditor.type,state.ruleEditor.id);state.verification=null;render();notify("Rule restored to its original automatic memory selection.");return;}if(event.target.closest("[data-delete-rule]")){const {type,id}=state.ruleEditor;state.creator=type==="goal"?emulator.removeMilestone(id):emulator.removeLossGuard(id);state.ruleEditor=null;state.verification=null;render();notify(type==="goal"?"Goal deleted.":"Loss guard deleted.");return;}const reinforceGoal=event.target.closest("[data-reinforce-goal]");if(reinforceGoal){const result=emulator.reinforceGoal(reinforceGoal.dataset.reinforceGoal);if(result.error)throw new Error(result.error);state.creator=emulator.creatorSummary();render();notify(`👍 ${result.milestone.title} reinforced.`);return;}const reinforceLoss=event.target.closest("[data-reinforce-loss]");if(reinforceLoss){const result=emulator.reinforceLoss(reinforceLoss.dataset.reinforceLoss);if(result.error)throw new Error(result.error);state.creator=emulator.creatorSummary();render();notify(`👎 ${result.guard.title} reinforced.`);return;}if(event.target.closest("[data-verify]")){if(state.creator?.mode==="verification"){emulator.creator.mode="review";emulator.creator.attempt=null;emulator.eventLedger=null;emulator.outcome=null;stopCreatorControl();state.creator=emulator.creatorSummary();state.verification=null;render();notify("Verification stopped.");return;}state.creator=emulator.verify();state.creatorControl=true;state.verification={status:"running"};render();notify("Verification running.");return;}const transport=event.target.closest("[data-transport]")?.dataset.transport;if(transport==="restart")return await loadGame(state.game,"moment");if(["back60","back","play","forward","forward60"].includes(transport)&&!hasRecordedFrames())return;if(transport==="play"){if(state.live){stopTimelineActivity();render();notify("Recording paused; timeline ready to scrub.");return;}timeline.togglePlay();render();return;}if(transport==="back60"){stopTimelineActivity();await timeline.seekTo(Math.max(0,timeline.currentFrame-60));render();return;}if(transport==="back"){stopTimelineActivity();await timeline.stepBackward();render();return;}if(transport==="forward"){stopTimelineActivity();await timeline.stepForward();render();return;}if(transport==="forward60"){stopTimelineActivity();await timeline.seekTo(Math.min(timeline.movie.totalFrames,timeline.currentFrame+60));render();return;}if(transport==="record"){timeline.pause();state.live=!state.live;state.inputMask=0;if(state.live&&timeline.currentFrame<(timeline.movie?.totalFrames||0))timeline.branchFromFrame(timeline.currentFrame);render();notify(state.live?"Recording live gameplay.":"Recording paused; timeline ready to scrub.");return;}const speed=event.target.closest("[data-speed]");if(speed){timeline.setSpeed(Number(speed.dataset.speed));render();return;}if(event.target.closest("[data-control-game]")){state.creatorControl=!state.creatorControl;if(!state.creatorControl){state.pressed.clear();state.inputMask=0;}render();notify(state.creatorControl?"Gameplay control active.":"Gameplay control paused.");return;}const demo=event.target.closest("[data-demo]")?.dataset.demo;if(demo==="start"){state.creator=emulator.beginAttempt("recording");state.creatorControl=true;state.verification=null;render();notify("Demonstration running. Mark new rules or reinforce existing ones.");return;}if(demo==="goal"){const result=emulator.tagMilestone();if(result.error)throw new Error(result.error);state.creator=emulator.creatorSummary();render();notify("Goal condition learned. ⚡");return;}if(demo==="loss"){const result=emulator.tagNewLoss();if(result.error)throw new Error(result.error);state.creator=emulator.creatorSummary();render();notify("Loss guard learned. ✕");return;}if(demo==="stop"){emulator.creator.mode="review";emulator.creator.attempt=null;stopCreatorControl();state.creator=emulator.creatorSummary();render();notify("Demonstration stopped.");return;}}catch(error){notify(error.message);}});
root.addEventListener("submit",async event=>{event.preventDefault();try{if(event.target.id==="memory-export-form"){event.stopImmediatePropagation();const fields=Object.fromEntries(new FormData(event.target)),name=String(fields.name||"").trim(),address=parseMemoryAddress(fields.address);if(!/^[A-Za-z_][A-Za-z0-9_]*$/.test(name))throw new Error("Variable names must start with a letter or underscore and contain only letters, numbers, and underscores.");if(address===null)throw new Error("Enter a hexadecimal memory address from $0000 to $FFFF.");if((emulator.creator.memoryExports||[]).some(item=>item.name.toLowerCase()===name.toLowerCase()))throw new Error(`The variable “${name}” already exists.`);emulator.creator.memoryExports||=[];emulator.creator.memoryExports.push({id:`export-${Date.now().toString(36)}`,name,address});state.creator=emulator.creatorSummary();render();notify(`Added “${name}” to the board-game interface.`);return;}if(event.target.id==="challenge-form")return await saveChallenge(event.target);if(event.target.id==="rule-editor-form"){const form=new FormData(event.target),type=event.target.dataset.ruleType,id=event.target.dataset.ruleId;emulator.renameCreatorRule(type,id,form.get("title"));state.creator=type==="goal"?emulator.updateMilestoneCondition(id,form.getAll("candidate")):emulator.updateLossGuardCondition(id,form.getAll("candidate"));state.ruleEditor=null;state.verification=null;render();notify(type==="goal"?"Goal updated.":"Loss guard updated.");}}catch(error){notify(error.message);}});
function gameBitForKey(key){const action=Object.keys(nesBits).find(name=>state.controls.keyboard[name]===key);return action===undefined?null:nesBits[action];}
function updateKeyboardMask(){state.inputMask=bitsToMask(state.pressed);}
document.addEventListener("keydown",event=>{if(!state.live&&!state.creatorControl)return;const bit=gameBitForKey(event.key.toLowerCase());if(bit===null)return;event.preventDefault();state.pressed.add(bit);updateKeyboardMask();});
document.addEventListener("keyup",event=>{const bit=gameBitForKey(event.key.toLowerCase());if(bit===null)return;state.pressed.delete(bit);updateKeyboardMask();});
window.addEventListener("blur",()=>{state.pressed.clear();updateKeyboardMask();});
function gameLoop(){if(emulator.core&&(state.live||state.creatorControl)){applyScoreLocks();const pad=firstConnectedGamepad(navigator.getGamepads?.()),inputMask=state.inputMask|gamepadInputMask(pad,state.controls.gamepad),output=emulator.runFrame(inputMask);if(state.live)timeline.recordLiveFrame(inputMask,output);drawOutput(document.querySelector(state.stage==="moment"?"#moment-canvas":"#designer-canvas"),output);if(state.stage==="designer"&&emulator.creator){updateScoreRuntime();state.creator=emulator.creatorSummary();if(state.verification?.status==="running")updateVerificationDisplay();if(output.outcome&&state.verification?.status==="running")finishVerification(output.outcome);}}requestAnimationFrame(gameLoop);}
async function loadCatalog(){const catalog=await api("/api/catalog");state.catalog={games:catalog.games||[],challenges:catalog.challenges||[]};}
async function loadControls(){try{const controls=await api("/api/controls");state.controls={keyboard:{...defaultControls.keyboard,...(controls.keyboard||{})},gamepad:{...defaultControls.gamepad,...(controls.gamepad||{})}};}catch(error){console.warn("Could not load saved controls; using defaults.",error);}}
window.addEventListener("popstate",()=>{stopTimelineActivity();state.creatorControl=false;state.stage="games";render();});
(async()=>{try{await Promise.all([loadCatalog(),loadControls()]);state.stage="games";render();requestAnimationFrame(gameLoop);}catch(error){root.innerHTML=`<section class="maker-loading">${html(error.message)}</section>`;}})();
